import re, secrets
from flask import session, abort, render_template_string

def install(application):
    from app import can_edit, home as base_home
    from editor_upgrade import SELECTORS, FONTS
    @application.get('/studio')
    def studio():
        if not can_edit():
            abort(403)
        page = base_home()
        page = re.sub(r'<script\b[^>]*>.*?</script>', '', page, flags=re.S)
        page = re.sub(r'<aside\b[^>]*>.*?</aside>', '', page, flags=re.S)
        tools = render_template_string(UI, csrf=session.setdefault('csrf', secrets.token_urlsafe(32)), uid=session['uid'], selectors=SELECTORS, fonts=FONTS)
        page = page.replace('<div class="wrap">', tools + '<div id="s-workspace"><div class="wrap">', 1)
        return page.replace('</body>', '</div>' + render_template_string(SCRIPT, csrf=session['csrf'], uid=session['uid'], selectors=SELECTORS, fonts=FONTS) + '</body>')
    original = application.view_functions['home']
    def home():
        page = original()
        if can_edit():
            page = page.replace('</body>', '<a href="/studio" style="position:fixed;top:12px;right:12px;z-index:1100;background:#6347cf;color:white;padding:12px 18px;border-radius:12px;font:14px Arial;text-decoration:none">Open design studio ↗</a></body>')
        return page
    application.view_functions['home'] = home

